-- =====================================================
-- SCHEMA: enums
-- Purpose: Dictionary tables (template section 4.4 shape). UI labels come from i18n
--          (enums.<name>.<value>); *_label is the English default.
-- user_account_role, permission and role_permission INSERT blocks are GENERATED by
-- scripts/build-role-permission-seed.js from packages/modules/shared/permissions.js
-- (npm run build-role-permission-seed). Do not edit them by hand.
-- =====================================================
CREATE SCHEMA IF NOT EXISTS enums;

-- -----------------------------------------------------
