-- -----------------------------------------------------
-- Table: enums.role_permission
-- Purpose: Role to permission grants (generated from packages/modules/shared/permissions.js)
-- -----------------------------------------------------
CREATE TABLE enums.role_permission (
    role_permission_id BIGINT GENERATED ALWAYS AS IDENTITY UNIQUE NOT NULL,
    role_permission_role VARCHAR(100) NOT NULL,
    role_permission_permission VARCHAR(100) NOT NULL,
    PRIMARY KEY (role_permission_role, role_permission_permission),
    CONSTRAINT fk_role_permission_role FOREIGN KEY (role_permission_role)
        REFERENCES enums.user_account_role(user_account_role_value) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_role_permission_permission FOREIGN KEY (role_permission_permission)
        REFERENCES enums.permission(permission_value) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX idx_role_permission_permission ON enums.role_permission(role_permission_permission);
